// Make HTTP request to Ollama using fetch
const requestBody = {
  model: "phi:latest",
  messages: [
    {
      role: "user",
      content: "Generate a coding task for a student bootcamp. The task should be: 1) Practical and hands-on 2) Suitable for intermediate level students 3) Include clear learning objectives 4) Have estimated duration of 60-120 minutes. Format as JSON with fields: title, description, difficulty_level, category, estimated_duration, learning_objectives (array)."
    }
  ],
  stream: false
};

try {
  const response = await fetch('http://ollama:11434/api/chat', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(requestBody)
  });

  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }

  const data = await response.json();
  return { json: data };
} catch (error) {
  // Fallback: create a default task if Ollama fails
  return {
    json: {
      message: {
        content: JSON.stringify({
          title: "Build a REST API with Express.js",
          description: "Create a simple REST API using Node.js and Express. Include endpoints for CRUD operations on a resource of your choice. Implement proper error handling and input validation.",
          difficulty_level: "intermediate",
          category: "Backend Development",
          estimated_duration: 120,
          learning_objectives: ["Learn Express.js framework", "Understand REST principles", "Practice API design"]
        })
      }
    }
  };
}

// Parse Ollama chat response and format for database
const ollamaResponse = $input.first().json;
const responseText = ollamaResponse.message?.content || ollamaResponse.response || 'No response';

// Try to extract JSON from the response
let taskData;
try {
  // Look for JSON in the response
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    taskData = JSON.parse(jsonMatch[0]);
  } else {
    // Fallback: create structured data from text
    taskData = {
      title: "AI Generated Task",
      description: responseText,
      difficulty_level: "intermediate",
      category: "Programming",
      estimated_duration: 90,
      learning_objectives: ["Learn new concepts", "Practice coding"]
    };
  }
} catch (error) {
  // If parsing fails, create default structure
  taskData = {
    title: "AI Generated Task",
    description: responseText,
    difficulty_level: "intermediate",
    category: "Programming",
    estimated_duration: 90,
    learning_objectives: ["Learn new concepts", "Practice coding"]
  };
}

// Handle estimated_duration - if it's an array, take the first value
if (Array.isArray(taskData.estimated_duration)) {
  taskData.estimated_duration = taskData.estimated_duration[0] || 90;
}

// Ensure learning_objectives is an array
if (!Array.isArray(taskData.learning_objectives)) {
  taskData.learning_objectives = ["Learn new concepts", "Practice coding"];
}

// Add metadata
return {
  json: {
    ...taskData,
    generated_by_ai: true,
    created_at: new Date().toISOString()
  }
};

// Format data for PostgreSQL insertion
const taskData = $input.first().json;

// Ensure learning_objectives is properly formatted as JSON string for JSONB
const formattedData = {
  title: taskData.title,
  description: taskData.description,
  difficulty_level: taskData.difficulty_level,
  category: taskData.category,
  estimated_duration: taskData.estimated_duration,
  learning_objectives: JSON.stringify(taskData.learning_objectives),
  generated_by_ai: taskData.generated_by_ai
};

return { json: formattedData };

// Create summary of the automation run
const taskData = $input.first().json;
const summary = {
  message: `✅ Task Generation Complete!

📋 New Task Created:
- Title: ${taskData.title || 'AI Generated Task'}
- Category: ${taskData.category || 'Programming'}
- Difficulty: ${taskData.difficulty_level || 'intermediate'}
- Duration: ${taskData.estimated_duration || 90} minutes

🎯 Assigned to Spring 2024 cohort students
📊 Stored in PostgreSQL
🤖 Generated by Ollama AI
⏰ Triggered at 6:00 AM daily

Timestamp: ${new Date().toLocaleString()}`,
  task_id: taskData.id,
  timestamp: new Date().toISOString()
};

return { json: summary };
